#ifndef DataFormatsMathfastRandomTwoSingle_H
#define DataFormatsMathfastRandomTwoSingle_H

#include <tuple>
#include <cstdint>
#include "CLHEP/Random/RandomEngine.h"

namespace fastRandom {

  // "generate two single precision number in [0,1[ out of a double precision one in the same interval (as for instance generated by CLHEP...)
  inline std::pair<float, float> twoSingle(double d) {
    union DInt {
      double d;
      uint64_t l;
    };
    union FInt {
      float f;
      uint32_t i;
    };
    DInt di;
    FInt fi;
    di.d = d + 1.;
    //    get 2 float from one double
    fi.i = (di.l & 0x007FFFFF) | 0x3F800000;  // extract mantissa as an FP number
    auto s1 = fi.f - 1.f;
    di.l = (di.l >> 23ul);  // remove those used
    //    repeat
    fi.i = (di.l & 0x007FFFFF) | 0x3F800000;  // extract mantissa as an FP number
    auto s2 = fi.f - 1.f;
    return {s1, s2};
  }

  class OneFloat {
  public:
    OneFloat() = default;
    explicit OneFloat(CLHEP::HepRandomEngine& engine) : m_engine(&engine) {}

    void reset(CLHEP::HepRandomEngine& engine) {
      m_ready = false;
      m_engine = &engine;
    }

    float operator()() { return nextRN(); }

    float operator()(CLHEP::HepRandomEngine& engine) {
      // for safety we assume it is a new engine
      reset(engine);
      return (*this)();
    }

  private:
    float nextRN() {
      if (m_ready) {
        m_ready = false;
        return m_rn.second;
      }
      m_rn = twoSingle(*m_engine);
      m_ready = true;
      return m_rn.first;
    }

    CLHEP::HepRandomEngine* m_engine = nullptr;
    ;
    std::pair<float, float> m_rn;
    bool m_ready = false;
  };

}  // namespace fastRandom
#endif
